package com.aoo.bcg.common.resource;
import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.file.*;import java.util.zip.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class TemporaryFileScopeTest{@TempDir Path directory;
 @Test void cleansUploadAndReplayStagingOnSuccessAndFailure(){Path first;try(var scope=new TemporaryFileScope(directory,"upload-")){first=scope.root();scope.copyUpload(new ByteArrayInputStream("ok".getBytes()),"replay.bin",10);}assertFalse(Files.exists(first));Path second;try(var scope=new TemporaryFileScope(directory,"upload-")){second=scope.root();assertThrows(IllegalArgumentException.class,()->scope.copyUpload(new ByteArrayInputStream("too-large".getBytes()),"upload.bin",2));}assertFalse(Files.exists(second));}
 @Test void rejectsZipSlipAndRemovesPartialExtraction()throws Exception{var bytes=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(bytes)){zip.putNextEntry(new ZipEntry("safe/a.txt"));zip.write(1);zip.closeEntry();zip.putNextEntry(new ZipEntry("../../escape.txt"));zip.write(2);zip.closeEntry();}Path root;try(var scope=new TemporaryFileScope(directory,"zip-")){root=scope.root();assertThrows(SecurityException.class,()->scope.extractZip(new ByteArrayInputStream(bytes.toByteArray()),10,100));}assertFalse(Files.exists(root));assertFalse(Files.exists(directory.resolve("escape.txt")));}
}
